<?php /** The lines grouped by provider / department / agent / model. Data: s, lines (rows, totals, group_by) */ $id = (int) $s['ai_statement_id']; $g = $lines['group_by']; ?>
<div class="card mb-3" id="ai-lines"><div class="card-header"><h5 class="card-title mb-0">Usage by <?= e(strtolower(AI_GROUPS[$g])) ?></h5>
    <span class="d-flex gap-1 flex-wrap" id="ai-lines-groups"><?php foreach (AI_GROUPS as $k => $label): ?><?= hx_link('/ap/ai/' . $id . '?group_by=' . $k, e($label), 'btn btn-sm ' . ($g === $k ? 'btn-primary' : 'btn-light'), 'id="ai-lines-group-' . $k . '"') ?><?php endforeach; ?></span></div>
    <?php if ($lines['rows'] === []): ?><div class="card-body text-muted" id="ai-lines-empty">No usage on this statement.</div><?php else: ?>
    <div class="table-responsive"><table class="table table-sm mb-0" id="ai-lines-table"><thead><tr><th><?= e(AI_GROUPS[$g]) ?></th><th class="text-end">Calls</th><th class="text-end">Late</th><th class="text-end">Input</th><th class="text-end">Output</th><th class="text-end">Amount</th></tr></thead><tbody>
        <?php foreach ($lines['rows'] as $i => $r): ?><tr id="ai-line-<?= $i ?>"><td><?= e((string) $r['grp']) ?></td><td class="text-end"><?= number_format($r['calls']) ?></td><td class="text-end <?= $r['late_calls'] > 0 ? 'text-warning' : 'text-muted' ?>"><?= number_format($r['late_calls']) ?></td><td class="text-end text-muted"><?= number_format($r['input_tokens']) ?></td><td class="text-end text-muted"><?= number_format($r['output_tokens']) ?></td><td class="text-end text-nowrap"><?= e($r['amount']) ?> <span class="text-muted fs-12"><?= e($r['currency']) ?></span></td></tr><?php endforeach; ?>
    </tbody><tfoot id="ai-lines-totals"><?php foreach ($lines['totals'] as $t): ?><tr class="fw-bold"><td>Total <?= e($t['currency']) ?></td><td class="text-end"><?= number_format($t['calls']) ?></td><td class="text-end"><?= number_format($t['late_calls']) ?></td><td class="text-end"><?= number_format($t['input_tokens']) ?></td><td class="text-end"><?= number_format($t['output_tokens']) ?></td><td class="text-end text-nowrap" id="ai-lines-total-<?= e($t['currency']) ?>"><?= e($t['amount']) ?> <?= e($t['currency']) ?></td></tr><?php endforeach; ?></tfoot></table></div><?php endif; ?>
</div>
